import{_ as a,o as t,c as s,a2 as n}from"./chunks/framework.BU4O3IzQ.js";const d=JSON.parse('{"title":"AI 动态 · 2026-07-31","description":"","frontmatter":{"title":"AI 动态 · 2026-07-31","date":"2026-07-31T00:00:00.000Z","outline":[2,3]},"headers":[],"relativePath":"news/2026-07/ai-news-2026-07-31.md","filePath":"news/2026-07/ai-news-2026-07-31.md","lastUpdated":1786092171000}'),r={name:"news/2026-07/ai-news-2026-07-31.md"};function o(i,e,c,l,p,h){return t(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="ai-动态-·-2026-07-31" tabindex="-1">AI 动态 · 2026-07-31 <a class="header-anchor" href="#ai-动态-·-2026-07-31" aria-label="Permalink to &quot;AI 动态 · 2026-07-31&quot;">​</a></h1><blockquote><p>截至 2026-07-31。业界 · 产品 · 模型 · 开源 · 开发者工具 · 前端。</p></blockquote><div class="news-section" data-section="业界"><h2 id="业界" tabindex="-1">业界 <a class="header-anchor" href="#业界" aria-label="Permalink to &quot;业界&quot;">​</a></h2><h3 id="微软、meta-同日交财报-azure-大涨-41-meta-利润率承压" tabindex="-1">微软、Meta 同日交财报：Azure 大涨 41%，Meta 利润率承压 <a class="header-anchor" href="#微软、meta-同日交财报-azure-大涨-41-meta-利润率承压" aria-label="Permalink to &quot;微软、Meta 同日交财报：Azure 大涨 41%，Meta 利润率承压&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-31">2026-07-31</time></p><p><img src="https://static001.infoq.cn/resource/image/b1/a8/b1f461b5a4835a2ded46352815b65fa8.png" alt="配图"></p><p>微软与 Meta 同日公布财报，方向迥异。微软 2026 财年营收 3310 亿美元（+18%），Azure 达 1000 亿美元（+41%），盘后一度涨超 8%。Meta Q2 收入 608 亿美元（+28%），但成本同比激增 55%，营业利润率从 43% 降至 31%，净利润下降 14%，股价一度跌 10%。两家公司 AI 战略路径分化：微软变现加速，Meta 仍处重投入阶段。对读者：关注云服务成本趋势的团队，可留意 Azure 的持续增长对 AI 基础设施定价的潜在影响。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/cWloUAofMHCLHpvscihh?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="翁荔被爆重返-openai-两天前因身体原因从-thinking-machines-lab-离职" tabindex="-1">翁荔被爆重返 OpenAI，两天前因身体原因从 Thinking Machines Lab 离职 <a class="header-anchor" href="#翁荔被爆重返-openai-两天前因身体原因从-thinking-machines-lab-离职" aria-label="Permalink to &quot;翁荔被爆重返 OpenAI，两天前因身体原因从 Thinking Machines Lab 离职&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-31">2026-07-31</time></p><p><img src="https://static001.infoq.cn/resource/image/d8/ea/d81963e9b597d38e24993c2cb553a2ea.png" alt="配图"></p><p>翁荔（Lilian Weng）在从 Thinking Machines Lab 离职仅一天后重返 OpenAI，负责领导一支面向内部研究的高层级团队，支持包括“递归自我改进”在内的跨研究工作。她此前因联合创始人角色带来的持续高压退出创业公司，但并非离开 AI 研究本身。翁荔早期在 OpenAI 主导 Dactyl 魔方项目，后负责应用 AI 研究团队。对读者：关注 AI 人才流动与递归自我改进方向的从业者，可留意 OpenAI 在此领域的研究进展。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/im3GxWtxYPZpkodNRgVQ?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="siggraph-时间检验奖揭晓-这项研究提前十年押中物理-ai" tabindex="-1">SIGGRAPH 时间检验奖揭晓：这项研究提前十年押中物理 AI <a class="header-anchor" href="#siggraph-时间检验奖揭晓-这项研究提前十年押中物理-ai" aria-label="Permalink to &quot;SIGGRAPH 时间检验奖揭晓：这项研究提前十年押中物理 AI&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-31">2026-07-31</time></p><p>2026 年 SIGGRAPH 时间检验奖授予港大教授 Taku Komura 团队 2016 年发表的《A Deep Learning Framework for Character Motion Synthesis and Editing》。该工作首次用深度学习从大规模动作数据中学习人类运动结构，再根据高层指令生成自然动作，被视为物理 AI 的早期奠基工作。其开源项目在 GitHub 已获 8000+ Star。对读者：关注物理 AI 与动作生成的研究者，可回溯该论文及其后续工作，理解数据驱动运动表示的技术脉络。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/464328.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="产品"><h2 id="产品" tabindex="-1">产品 <a class="header-anchor" href="#产品" aria-label="Permalink to &quot;产品&quot;">​</a></h2><p>（本日无新条目）</p></div><div class="news-section" data-section="模型"><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><h3 id="minimax-发布首个开源视频模型-h3-手绘即特效" tabindex="-1">MiniMax 发布首个开源视频模型 H3，手绘即特效 <a class="header-anchor" href="#minimax-发布首个开源视频模型-h3-手绘即特效" aria-label="Permalink to &quot;MiniMax 发布首个开源视频模型 H3，手绘即特效&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-31">2026-07-31</time></p><p>MiniMax 正式发布全新一代视频模型 H3，也是其首个开源视频模型。H3 将剪辑逻辑、字体排版、转场设计、节奏把控、背景音乐及视觉特效端到端集成到模型中，输入文本即可直接生成可发布的成品视频，默认清晰度 2K。社区公认其为新的 SOTA 视频模型，在 Artificial Analysis 榜单上斩获视频编辑第一，也是唯一开放权重的第一名。对读者：视频创作者可关注 H3 的开源权重，探索将后期制作流程前置到生成阶段，大幅降低剪辑门槛。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/464277.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="字节发布-seedance-2-5-支持-30-秒视频原生直出" tabindex="-1">字节发布 Seedance 2.5，支持 30 秒视频原生直出 <a class="header-anchor" href="#字节发布-seedance-2-5-支持-30-秒视频原生直出" aria-label="Permalink to &quot;字节发布 Seedance 2.5，支持 30 秒视频原生直出&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">量子位</span><time datetime="2026-07-31">2026-07-31</time></p><p>字节跳动正式发布自研视频模型 Seedance 2.5，即梦 AI 作为官方体验入口已第一时间接入。新模型支持行业独家的 30 秒视频原生直出，最长可达 3 分钟超长视频生成；新增视频编辑功能，支持局部修改、增加、删除、替换；参考生成能力至高同时参考 50 个素材，支持白模和绿幕素材，可接入 Maya/Blender 插件；精准时间戳指令误差控制在 1 秒以内。对读者：需要长镜头、高一致性视频生成的创作者，可优先体验 Seedance 2.5 的原生直出能力，减少后期拼接工作量。</p><p class="news-entry-source"><a href="https://www.qbitai.com/2026/07/464329.html" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开源"><h2 id="开源" tabindex="-1">开源 <a class="header-anchor" href="#开源" aria-label="Permalink to &quot;开源&quot;">​</a></h2><h3 id="github-发布-copilot-sdk-支持多平台集成-copilot-agent" tabindex="-1">GitHub 发布 Copilot SDK，支持多平台集成 Copilot Agent <a class="header-anchor" href="#github-发布-copilot-sdk-支持多平台集成-copilot-agent" aria-label="Permalink to &quot;GitHub 发布 Copilot SDK，支持多平台集成 Copilot Agent&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">github/copilot-sdk</span><time datetime="2026-07-31">2026-07-31</time></p><p><img src="https://opengraph.githubassets.com/1/github/copilot-sdk" alt="配图"></p><p>GitHub 正式发布 copilot-sdk，这是一个多平台 SDK，用于将 GitHub Copilot Agent 集成到各类应用和服务中。该 SDK 为开发者提供了将 Copilot 能力嵌入自有产品的官方途径，涵盖从代码生成到 Agent 工作流的多种集成场景。对读者：希望在产品中集成 AI 编程能力的团队，可研究该 SDK 的接入方式，评估其与现有开发流程的契合度。</p><p class="news-entry-source"><a href="https://github.com/github/copilot-sdk" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="kaneo-开源项目管理工具-主打简洁实用" tabindex="-1">Kaneo：开源项目管理工具，主打简洁实用 <a class="header-anchor" href="#kaneo-开源项目管理工具-主打简洁实用" aria-label="Permalink to &quot;Kaneo：开源项目管理工具，主打简洁实用&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">usekaneo/kaneo</span><time datetime="2026-07-31">2026-07-31</time></p><p><img src="https://opengraph.githubassets.com/1/usekaneo/kaneo" alt="配图"></p><p>Kaneo 是一个开源项目管理工具，定位为“All you need. Nothing you don&#39;t”，强调提供所需功能而不冗余。该项目面向希望自主掌控项目管理流程的团队，提供简洁的核心功能集。对读者：需要轻量级、可自托管项目管理方案的团队，可关注 Kaneo 的社区活跃度与功能完整性。</p><p class="news-entry-source"><a href="https://github.com/usekaneo/kaneo" target="_blank" rel="noopener noreferrer">阅读原文</a></p><h3 id="chatwoot-开源全渠道客服平台-替代-intercom-与-zendesk" tabindex="-1">Chatwoot：开源全渠道客服平台，替代 Intercom 与 Zendesk <a class="header-anchor" href="#chatwoot-开源全渠道客服平台-替代-intercom-与-zendesk" aria-label="Permalink to &quot;Chatwoot：开源全渠道客服平台，替代 Intercom 与 Zendesk&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">chatwoot/chatwoot</span><time datetime="2026-07-31">2026-07-31</time></p><p><img src="https://opengraph.githubassets.com/1/chatwoot/chatwoot" alt="配图"></p><p>Chatwoot 是一个开源的全渠道客服平台，支持在线聊天、邮件支持和全渠道工单管理，定位为 Intercom、Zendesk、Salesforce Service Cloud 等商业产品的替代方案。该项目提供自托管能力，适合对数据隐私和定制化有要求的企业。对读者：正在评估客服系统选型的企业，可将 Chatwoot 作为低成本、可私有化部署的候选方案进行对比测试。</p><p class="news-entry-source"><a href="https://github.com/chatwoot/chatwoot" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="开发者工具"><h2 id="开发者工具" tabindex="-1">开发者工具 <a class="header-anchor" href="#开发者工具" aria-label="Permalink to &quot;开发者工具&quot;">​</a></h2><h3 id="github-ai-agent-翻车-攻击者只写一句话就能窃取数据" tabindex="-1">GitHub AI Agent 翻车：攻击者只写一句话就能窃取数据 <a class="header-anchor" href="#github-ai-agent-翻车-攻击者只写一句话就能窃取数据" aria-label="Permalink to &quot;GitHub AI Agent 翻车：攻击者只写一句话就能窃取数据&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-31">2026-07-31</time></p><p><img src="https://static001.infoq.cn/resource/image/44/7b/44a4df7cf7d617b7c8bb32e9e6d6e37b.jpg" alt="配图"></p><p>Noma Security 发现一种名为 GitLost 的提示注入漏洞利用方式，可诱骗 GitHub 新推出的 Agentic Workflows 泄露私有数据。攻击者无需任何编程技能或凭据，只需在公开仓库中创建一个 Issue，嵌入隐藏指令即可诱导 AI Agent 在公开评论中泄露机密信息。研究人员建议用户控制的内容不应被视为可信指令输入，Agent 权限应限制在严格必要范围内。对读者：使用 GitHub Agentic Workflows 的团队应审查 Agent 权限范围，并限制其可公开披露的信息。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/u4rDqep8zVWUJsqVoQ23?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div><div class="news-section" data-section="前端"><h2 id="前端" tabindex="-1">前端 <a class="header-anchor" href="#前端" aria-label="Permalink to &quot;前端&quot;">​</a></h2><h3 id="react-compiler-迁移-rust-后更快了-但开发者担心-没人看得懂代码" tabindex="-1">React Compiler 迁移 Rust 后更快了，但开发者担心“没人看得懂代码” <a class="header-anchor" href="#react-compiler-迁移-rust-后更快了-但开发者担心-没人看得懂代码" aria-label="Permalink to &quot;React Compiler 迁移 Rust 后更快了，但开发者担心“没人看得懂代码”&quot;">​</a></h3><p class="news-entry-meta"><span class="news-source-tag">InfoQ 中文</span><time datetime="2026-07-31">2026-07-31</time></p><p><img src="https://static001.infoq.cn/resource/image/f6/aa/f632c03cb115c7440a26a7d5799853aa.jpg" alt="配图"></p><p>Meta 已将 React Compiler 的 Rust 移植版本合并到主代码仓库。该编译器从 TypeScript 重写为 Rust，作为 Babel 插件运行时速度约为原版的 3 倍，独立转换逻辑最高可达 10 倍提升。直接集成到 Turbopack 后，Vercel 内部大规模应用编译速度提升超 40%，Next.js 16.3 将提供实验性支持。此次移植大量依赖 LLM 完成机械性工作，引发开发者对代码可维护性的担忧。对读者：关注 React 生态的可跟进 Next.js 16.3 实验特性，评估 Rust 编译器带来的构建提速收益。</p><p class="news-entry-source"><a href="https://www.infoq.cn/article/xeM23uOSNw0s7Q8xUCTp?utm_source=rss&amp;utm_medium=article" target="_blank" rel="noopener noreferrer">阅读原文</a></p></div>',8)])])}const u=a(r,[["render",o]]);export{d as __pageData,u as default};
